Let me write a magnitude subtraction:

```rust
fn sub_magnitude(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // assumes a.len() == b.len() and a >= b
    let mut borrow = 0u8;
    let mut out = vec![0u8; a.len()];
    for i in (0..a.len()).rev() {
        let mut t = a[i] as i16 - b[i] as i16 - borrow as i16;
        if t < 0 { t += 10; borrow = 1; } else { borrow = 0; }
        out[i] = t as u8;
    }
    out
}
```

cmp_magnitude: align scales, compare digit vectors lexicographically.

Actually, for a simpler, more unified approach: implement `add` as:

```rust
pub fn add(&self, other: &Decimal) -> Decimal {
    let (mut a, sa) = self.magnitude();
    let (mut b, sb) = other.magnitude();
    let n = a.len().max(b.len());
    while a.len() < n { a.insert(0, 0); }
    while b.len() < n { b.insert(0, 0); }
    let scale = sa.max(sb);
    if self.neg == other.neg {
        let mut carry = 0u8;
        let mut sum = vec![0u8; n];
        for i in (0..n).rev() {
            let t = a[i] as u16 + b[i] as u16 + carry as u16;
            sum[i] = (t % 10) as u8;
            carry = (t / 10) as u8;
        }
        if carry > 0 { sum.insert(0, carry); }
        Decimal::from_magnitude(sum, scale, self.neg)
    } else {
        // compare magnitudes
        let cmp = sum_cmp(&a, &b); // a and b same length, so lexicographic
        match cmp {
            Ordering::Equal => Decimal::zero(),
            Ordering::Greater => {
                let diff = sub_magnitude(a, b);
                Decimal::from_magnitude(diff, scale, self.neg)
            }
            Ordering::Less => {
                let diff = sub_magnitude(b, a);
                Decimal::from_magnitude(diff, scale, other.neg)
            }
        }
    }
}
```

Since a and b are the same length after padding, lexicographic comparison works.

Mul:

```rust
pub fn mul(&self, other: &Decimal) -> Decimal {
    let (a, sa) = self.magnitude();
    let (b, sb) = other.magnitude();
    if a.is_empty() || b.is_empty() {
        return Decimal::zero();
    }
    let mut prod = vec![0u8; a.len() + b.len()];
    for (i, &da) in a.iter().enumerate().rev() {
        for (j, &db) in b.iter().enumerate().rev() {
            let t = prod[i + j] as u16 + da as u16 * db as u16;
            prod[i + j] = (t % 10) as u8;
            prod[i + j + 1] += (t / 10) as u8;
        }
    }
    Decimal::from_magnitude(prod, sa + sb, self.neg ^ other.neg)
}
